        style=f"background-image:url('../{SPRITE}');background-size:100% 700%;background-position:center {item['sprite_pos']};background-repeat:no-repeat"
        return f'''<div class="project-visual rounded-xl mb-8 relative" style="{style}"><span class="ai-badge">AI-GENERATED VISUALIZATION</span></div>'''
