        return f'''<div class="project-visual rounded-xl mb-8 relative overflow-hidden"><img src="{esc(item['image'])}" alt="{esc(item['title'])}" class="w-full h-full object-cover"><span class="source-badge">PROJECT MEDIA</span></div>'''
